import Image from "next/image";
import Link from "next/link";
import { pdfBlocks } from "@/lib/pdf-docs";

// Thumbnails are generated by `pnpm --filter @repo/registries pdf:previews`.
const thumbnail = (name: string) => `/previews/pdf/${name}-1.png`;

export function BlockGrid() {
  return (
    <div className="not-prose grid grid-cols-1 gap-x-6 gap-y-8 sm:grid-cols-2">
      {pdfBlocks.map((block) => (
        <Link
          className="group flex flex-col gap-3"
          href={block.href}
          key={block.name}
        >
          <div className="relative aspect-[4/5] overflow-hidden rounded-lg border bg-muted transition-colors group-hover:border-foreground/30">
            <Image
              alt={`${block.title} PDF block preview`}
              className="object-contain p-4 drop-shadow-md transition-transform duration-300 group-hover:scale-[1.02]"
              fill
              sizes="(min-width: 1024px) 380px, (min-width: 640px) 45vw, 100vw"
              src={thumbnail(block.name)}
            />
          </div>
          <div className="flex flex-col gap-1">
            <span className="font-medium text-sm">{block.title}</span>
            <span className="text-muted-foreground text-sm leading-relaxed">
              {block.description}
            </span>
          </div>
        </Link>
      ))}
    </div>
  );
}
